"""Independent parser check. Requires python-can; input is generated by C++ test."""
import sys
import can

with can.ASCReader(sys.argv[1]) as reader:
    frames = list(reader)
assert len(frames) == 4
assert [f.arbitration_id for f in frames] == [0x123, 0x18DAF110, 0x7FF, 0]
assert [f.is_extended_id for f in frames] == [False, True, False, False]
assert [f.is_remote_frame for f in frames] == [False, False, True, False]
assert [f.dlc for f in frames] == [8, 2, 8, 0]
assert bytes(frames[0].data) == bytes([0, 1, 2, 3, 0xAA, 0xBB, 0xCC, 0xFF])
assert bytes(frames[1].data) == bytes([0, 1])
assert not frames[2].data and not frames[3].data
for frame, expected in zip(frames, [0, 1.234567, 4294.967300, 4294.967400]):
    assert abs(frame.timestamp - expected) < 0.000001
assert all(f.is_rx and f.channel == 0 for f in frames)  # ASC channel 1 maps to index 0.
print("Independent ASC import passed (4 mixed Classical CAN frames, elapsed time only)")
